import{c as t,J as o,h as r,k as i}from"./chunks/framework.WgZQdPFo.js";const h=JSON.parse('{"title":"Craft Web Store & Showcase","description":"Autonomous Static Site Generator (Jamstack SSG), Quiet Luxury design system, unified Order Inbox, and multi-transport deployment in OmniCraft ERP.","frontmatter":{"title":"Craft Web Store & Showcase","description":"Autonomous Static Site Generator (Jamstack SSG), Quiet Luxury design system, unified Order Inbox, and multi-transport deployment in OmniCraft ERP.","order":9},"headers":[],"relativePath":"docs/spaces/production/web-store.md","filePath":"docs/spaces/production/web-store.md","lastUpdated":1793765307000}'),a={name:"docs/spaces/production/web-store.md"};function s(n,e,l,d,c,u){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="craft-web-store-showcase" tabindex="-1">Craft Web Store &amp; Showcase <a class="header-anchor" href="#craft-web-store-showcase" aria-label="Permalink to &quot;Craft Web Store &amp; Showcase&quot;">​</a></h1><p>The built-in <strong>Web Store</strong> module transforms your workshop recipe catalog, warehouse inventory, and product photography into an autonomous, lightning-fast static website without dependence on proprietary site builders and without vulnerable server CMS platforms.</p><p>The showcase is compiled using static site generation (Jamstack SSG): the output consists of pure HTML, clean CSS, vanilla JavaScript, and optimized web-ready images. The generated website opens instantly on desktop and mobile devices, requires no database setup on your hosting server, and can be hosted for free on GitHub Pages, S3-compatible cloud storage, or standard web hosting via FTP.</p><hr><h2 id="version-v3-architecture-and-highlights" tabindex="-1">Version v3 Architecture and Highlights <a class="header-anchor" href="#version-v3-architecture-and-highlights" aria-label="Permalink to &quot;Version v3 Architecture and Highlights&quot;">​</a></h2><p>The next-generation showcase combines quiet luxury craft aesthetics with enterprise-grade engineering reliability:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Subsystem</th><th style="text-align:left;">Program Implementation</th><th style="text-align:left;">Workshop Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Quiet Luxury Design</strong></td><td style="text-align:left;">100% offline Inter WOFF2 typography, brass accents, light and dark themes with zero-flicker FOUC guard</td><td style="text-align:left;">Premium presentation for bespoke craft products with zero external CDN dependencies</td></tr><tr><td style="text-align:left;"><strong>Multi-page Structure</strong></td><td style="text-align:left;">Home storefront, faceted catalog with search, dedicated product pages, shipping/policy pages, and blog</td><td style="text-align:left;">A comprehensive brand website rather than a basic single-page price list</td></tr><tr><td style="text-align:left;"><strong>Modular Product Cards</strong></td><td style="text-align:left;">Section builder: lead summary, feature cards, craftsman story, additional photo galleries (lookbook), video embed, specification table, FAQ accordion</td><td style="text-align:left;">Engaging storytelling for one-of-a-kind and serialized pieces highlighting material quality</td></tr><tr><td style="text-align:left;"><strong>Sovereign Checkout &amp; E2EE</strong></td><td style="text-align:left;">Serverless cart, direct encryption (RSA-2048 + AES-256-GCM), Telegram Bot API and Yandex Forms</td><td style="text-align:left;">Complete independence from intermediaries, zero-knowledge privacy for customer contacts</td></tr><tr><td style="text-align:left;"><strong>Built-in Live Preview</strong></td><td style="text-align:left;">Multithreaded local HTTP server with strict no-cache headers for instant validation</td><td style="text-align:left;">Real-browser preview before deploying changes to production hosting</td></tr><tr><td style="text-align:left;"><strong>Universal Publishing Transport</strong></td><td style="text-align:left;">Local folder / ZIP, FTP/FTPS, S3 storages (Yandex Cloud, Selectel, AWS, MinIO), GitHub Pages</td><td style="text-align:left;">Rapid deployments in seconds thanks to SHA-256 incremental checksum verification</td></tr><tr><td style="text-align:left;"><strong>Unified Order Inbox</strong></td><td style="text-align:left;">Centralized incoming orders, smart clipboard parser, canned responses, and FIFO stock deduction</td><td style="text-align:left;">Zero inventory discrepancies and streamlined customer communication</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Independence from Third-Party Clouds</p><p>Unlike cloud e-commerce platforms, the <strong>OmniCraft ERP</strong> showcase cannot be disabled by platform bans, charges no hidden sales commissions, and embeds no third-party tracking scripts. All master data and customer records remain under your full control, and the published website belongs entirely to you.</p></div><hr><h2 id="showcase-architecture-and-layout" tabindex="-1">Showcase Architecture and Layout <a class="header-anchor" href="#showcase-architecture-and-layout" aria-label="Permalink to &quot;Showcase Architecture and Layout&quot;">​</a></h2><h3 id="_1-home-storefront-and-triptych-hero" tabindex="-1">1. Home Storefront and Triptych Hero <a class="header-anchor" href="#_1-home-storefront-and-triptych-hero" aria-label="Permalink to &quot;1. Home Storefront and Triptych Hero&quot;">​</a></h3><p>The home page introduces visitors to the workshop and highlights signature pieces:</p><ul><li><strong>Triptych Hero Section:</strong> combines the workshop value proposition, featured piece photography, and three value cards (e.g., traditional saddle stitch, vegetable-tanned leather, lifetime craftsmanship guarantee).</li><li><strong>Curated Work Showcase:</strong> highlighted pieces with distinct status badges (&quot;Hit&quot;, &quot;New&quot;, &quot;Custom Order&quot;, &quot;In Stock&quot;).</li><li><strong>Master&#39;s Word Block:</strong> personal craftsman column featuring author portrait photography, philosophy quote, and signature to establish direct client trust.</li></ul><h3 id="_2-product-page-and-quiet-luxury-architecture" tabindex="-1">2. Product Page and Quiet Luxury Architecture <a class="header-anchor" href="#_2-product-page-and-quiet-luxury-architecture" aria-label="Permalink to &quot;2. Product Page and Quiet Luxury Architecture&quot;">​</a></h3><p>The product detail page delivers a benchmark presentation experience for bespoke craftsmanship:</p><ul><li><strong>3D Triptych Gallery Slider (Cinematic Hero Gallery):</strong> full-width spatial gallery with real CSS depth (<code>perspective: 1200px</code>). The active center slide is flanked by angled preview cards at ±15° with smooth 3D translations, creating a physical triptych feel. Full touch-swipe support on mobile devices, arrow navigation, and dot indicators.</li><li><strong>Floating Hero Overlay:</strong> sits elegantly over the lower edge of the slider. Displays the product title, price, &quot;DETAILS ⌄&quot; smooth anchor button, and &quot;Other Colors&quot; trigger that opens a variant picker modal (3:4 aspect ratio cards with active badge).</li><li><strong>Adaptive Scrolled Mode Header:</strong> floating transparent navbar over the dark hero that smoothly transitions to an opaque frosted white background with subtle elevation shadow (<code>is-scrolled-mode</code>), fading in a centered product title, &quot;MENU&quot; trigger, and pill-shaped Cart button.</li><li><strong>Two-Column Detail Layout (<code>#product-details</code>):</strong><ul><li><strong>Left Sticky Purchase Panel:</strong> remains fixed in view during scrolling (<code>position: sticky; top: 100px;</code>). Features a bold 36px price, 56px styled dropdown selectors with 9px tracking micro-labels, quantity stepper, monumental 64px CTA button (&quot;ADD TO CART&quot;, 100px border radius), direct Telegram &amp; WhatsApp consultation shortcuts, technical specs list, luxury tier badge, and delivery snippet.</li><li><strong>Right Narrative &amp; Storytelling Column:</strong> author editorial layout — intro paragraph with traditional drop cap, divider, key advantages with crisp square bullet points, craftsman quote block with vertical bar and Georgia serif italics, signature, and stacked modular content sections.</li></ul></li><li><strong>Lower Curated and Reference Sections:</strong><ul><li><strong>&quot;Other Products&quot; Grid:</strong> 4-column responsive grid showcasing complementary masterworks with a centered &quot;VIEW ALL PRODUCTS&quot; button.</li><li><strong>FAQ Accordion:</strong> interactive expandable drawers addressing leather care, hardware durability, and warranty terms.</li></ul></li><li><strong>Sticky Mobile Buy Bar:</strong> pinned to the bottom of smartphone screens directly under the thumb, enabling instant purchase without scrolling back to top.</li></ul><p>The craftsman can freely arrange modular description blocks:</p><ul><li><strong>Lead Summary:</strong> emotional, high-contrast introductory statement.</li><li><strong>Features Grid:</strong> clean icon cards detailing structural and ergonomic highlights.</li><li><strong>Craftsman Story:</strong> narrative regarding leather selection, hand burnishing, or finishing.</li><li><strong>Additional Gallery:</strong> atmospheric photo collection showcasing pieces in context, in use (lookbook), or inside the workshop, with easy batch uploading.</li><li><strong>Video Showcase:</strong> lite-facade video adapter for VK, Rutube, or YouTube. External scripts do not load until the first play click, saving bandwidth and boosting page speed.</li><li><strong>Specifications Table:</strong> structured technical matrix (dimensions, leather grade, hardware, weight).</li><li><strong>FAQ Accordion:</strong> expandable drawers addressing maintenance advice and warranty terms.</li></ul><h3 id="_3-communication-channels-checkout-and-privacy" tabindex="-1">3. Communication Channels, Checkout, and Privacy <a class="header-anchor" href="#_3-communication-channels-checkout-and-privacy" aria-label="Permalink to &quot;3. Communication Channels, Checkout, and Privacy&quot;">​</a></h3><p>The system provides a comprehensive intake workflow for showcase orders:</p><ol><li><strong>Three Interaction and Checkout Modes:</strong><ul><li><strong>Direct WhatsApp Consultation:</strong> instant jump into chat with pre-populated order items, variant selections, and computed total.</li><li><strong>Direct Telegram Conversation:</strong> direct transition to private chat or workshop channel with an organized order card.</li><li><strong>Serverless Website Cart (Checkout):</strong> customers submit orders directly on the website without leaving for third-party platforms, with client-side phone validation and empty-cart guards.</li></ul></li><li><strong>End-to-End Encryption (Web Crypto API):</strong><ul><li>Customer order payloads (name, phone, shipping address, note) are encrypted directly in the buyer&#39;s browser using symmetric AES-256-GCM.</li><li>The symmetric key is sealed using asymmetric RSA-OAEP (2048-bit) with the showcase public key embedded into <code>crypto.js</code> at compile time.</li><li>The master private key is generated inside the desktop OmniCraft ERP application and secured with operating system hardware-backed encryption (Windows DPAPI). Third-party access to the private key is physically impossible.</li><li>Even if Telegram Bot API traffic or intake payloads are intercepted, personal data cannot be read without the craftsman&#39;s private key inside the desktop app (Zero-Knowledge transport).</li></ul></li><li><strong>Two Sovereign Intake Gateways:</strong><ul><li><strong>Official Telegram Bot API:</strong> direct dispatch of encrypted payloads from the buyer&#39;s browser to the craftsman&#39;s chat with zero intermediate servers.</li><li><strong>Yandex Forms:</strong> domestic form service for structured order intake with spam protection and spreadsheet export support.</li></ul></li><li><strong>Legal Compliance (152-FZ, 26.1 ZoZPP RF, and GDPR):</strong><ul><li>The compiler automatically generates <code>privacy.html</code> (Privacy Policy) and <code>terms.html</code> (Public Offer and return terms for bespoke craft products under Article 26.1 of the Russian Consumer Protection Act) populated with business tax ID and workshop credentials.</li><li>The checkout drawer enforces a mandatory consent checkbox with active links to both legal documents; order submission is blocked until explicit consent is given.</li></ul></li></ol><div class="info custom-block"><p class="custom-block-title">Privacy and Data Protection (152-FZ &amp; GDPR)</p><p>The built-in legal page generator compiles customized Privacy Policy and Terms of Service documents with your business credentials and tax ID. The checkout drawer includes a mandatory consent checkbox referencing both legal pages.</p></div><hr><h2 id="step-by-step-deployment-guide" tabindex="-1">Step-by-Step Deployment Guide <a class="header-anchor" href="#step-by-step-deployment-guide" aria-label="Permalink to &quot;Step-by-Step Deployment Guide&quot;">​</a></h2><h3 id="step-1-configure-profile-and-sections" tabindex="-1">Step 1. Configure Profile and Sections <a class="header-anchor" href="#step-1-configure-profile-and-sections" aria-label="Permalink to &quot;Step 1. Configure Profile and Sections&quot;">​</a></h3><ol><li>Navigate to <strong>Web Store</strong> → subtab <strong>Profile &amp; Styling</strong>.</li><li>In the vertical sidebar, open <strong>Brand &amp; Contacts</strong>: <ul><li><strong>Showcase Logo:</strong> upload a vector <strong>SVG</strong>, modern <strong>WebP / AVIF</strong>, or transparent <strong>PNG / JPG</strong> (includes instant live preview and one-click removal to revert to text branding).</li><li><strong>Product Photo Backdrop:</strong> select a harmonious background color for catalog cards and the product 3D slider (presets: &quot;Dark Graphite&quot;, &quot;Light Neutral&quot;, &quot;Pure White&quot;, &quot;Warm Linen&quot;, or a custom HEX code), or upload a background texture image (supports WebP, AVIF, SVG, PNG, and JPG). The texture scales to fit the card and creates a stylish backdrop behind transparent and studio photos.</li><li><strong>Store Name &amp; Tagline:</strong> specify your brand name (defaults to universal &quot;Online Store&quot;) and an optional tagline (omitted from the website when left empty).</li><li><strong>Contacts &amp; Story:</strong> enter your phone number, Telegram username (without <code>@</code>), WhatsApp number, contact email, city, and workshop story in Markdown format.</li></ul></li><li>In the <strong>Delivery Methods</strong> section, configure courier, pickup, and transport company shipping rates.</li><li>In the <strong>Legal &amp; 152-FZ</strong> section, enter business details and click <strong>Generate 152-FZ Templates</strong>.</li><li>In the <strong>Checkout &amp; Orders</strong> section, select your preferred ordering mode (direct messenger chat, standalone <code>order.php</code>, or Yandex Forms).</li><li>In the <strong>Catalog, Blog &amp; SEO</strong> section, configure blog visibility, currency symbol, and click <strong>Save Profile</strong>.</li></ol><h3 id="step-2-prepare-products-for-the-showcase" tabindex="-1">Step 2. Prepare Products for the Showcase <a class="header-anchor" href="#step-2-prepare-products-for-the-showcase" aria-label="Permalink to &quot;Step 2. Prepare Products for the Showcase&quot;">​</a></h3><ol><li>Open the <strong>Showcase Catalog</strong> subtab.</li><li>Select your preferred display mode in the right toolbar: <ul><li><strong>Showcase Grid 3:4:</strong> visual portrait cards showcasing items with 3:4 aspect ratio covers, marketing badges (&quot;Hit&quot;, &quot;New&quot;), and an instant publication status overlay.</li><li><strong>Compact Registry:</strong> dense tabular rows with thumbnails for quick inspection of extensive collections.</li></ul></li><li>Toggle the <strong>Publish</strong> switch for products that should appear online (accessible directly on the card cover in grid mode).</li><li>Click the configuration button (slider icon) next to the item: <ul><li>In <strong>General Properties</strong>, specify the URL slug, status badge, and retail web price.</li><li>In <strong>Photos</strong>, upload images, reorder them with ◄/► arrows, and select the card cover.</li><li>In <strong>Description Sections</strong>, add feature cards, specifications, or video demonstrations.</li></ul></li><li>Click <strong>Save Product Properties</strong>.</li></ol><h3 id="step-3-local-live-preview" tabindex="-1">Step 3. Local Live Preview <a class="header-anchor" href="#step-3-local-live-preview" aria-label="Permalink to &quot;Step 3. Local Live Preview&quot;">​</a></h3><p>Always verify your website locally prior to remote deployment:</p><ol><li>In the top showcase toolbar, click <strong>Live Preview</strong> (eye icon).</li><li>The system compiles the showcase from the active database, starts an internal multithreaded web server, and opens the site in your default browser.</li><li>Test dark/light theme switching, catalog filters, and order submission flows.</li></ol><div class="warning custom-block"><p class="custom-block-title">Strict Cache Policy</p><p>The preview server sends <code>no-cache</code> and <code>must-revalidate</code> HTTP headers, ensuring that edits saved in OmniCraft ERP appear immediately upon refreshing your browser (F5).</p></div><h3 id="step-4-configure-transport-and-deploy" tabindex="-1">Step 4. Configure Transport and Deploy <a class="header-anchor" href="#step-4-configure-transport-and-deploy" aria-label="Permalink to &quot;Step 4. Configure Transport and Deploy&quot;">​</a></h3><ol><li>Open the <strong>Publishing Transport</strong> subtab.</li><li>Select your hosting method from the verified deployment triad: <ul><li><strong>Cloudflare Pages Direct Upload:</strong> instant deployment of static assets without build containers or repository clutter; global CDN and automated SSL certificate.</li><li><strong>S3 Cloud Storage (Yandex Cloud, Selectel, VK Cloud, MinIO):</strong> cost-effective, scalable, and sovereign static hosting supporting custom workshop domains.</li><li><strong>FTP / SFTP Protocol:</strong> direct upload to traditional shared web hosting or private servers via secure file transfer protocols.</li><li><strong>Local Folder / ZIP:</strong> save the site bundle to local disk for offline distribution or manual backup.</li><li><strong>GitHub Pages:</strong> automatic deployment to the <code>gh-pages</code> branch using the official REST API.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">&quot;One Site — One Service&quot; Principle and Eliminating Git Blobs</p><p>For bespoke craft showcases with dozens of high-resolution product photographs (WebP/AVIF), deploying via Git repository commits is strongly discouraged. Every new photo or catalog edit inflates the hidden <code>.git</code> folder, rapidly hitting free repository limits (1–2 GB) and degrading repository performance.</p><p>Direct deployment via <strong>Cloudflare Pages Direct Upload</strong> or <strong>S3 Object Storage</strong> uploads only modified files based on SHA-256 checksum diffing, keeps your version history lean, and delivers maximum deployment speed.</p></div><ol start="3"><li>Click <strong>Test Connection</strong>. Credentials are encrypted using Windows DPAPI.</li><li>Click <strong>Save Transport</strong>, then click <strong>Publish Website</strong> in the top toolbar. To access your deployed showcase, click <strong>Open Website</strong> (the button activates only after the first successful deployment in the active workspace; hovering over the disabled button displays an explanatory tooltip).</li></ol><hr><h2 id="order-inbox-workflow" tabindex="-1">Order Inbox Workflow <a class="header-anchor" href="#order-inbox-workflow" aria-label="Permalink to &quot;Order Inbox Workflow&quot;">​</a></h2><p>All orders from the website and external channels arrive in the <strong>Order Inbox</strong> subtab:</p><ol><li><strong>Sync Orders Button:</strong> clicking the <strong>&quot;🔄 Sync&quot;</strong> button in the Order Inbox toolbar: <ul><li>Connects to the official Telegram Bot API (<code>getUpdates</code>) and fetches new incoming messages;</li><li>Detects encrypted E2EE payloads and automatically decrypts them using the craftsman&#39;s RSA private key;</li><li>Accurately parses plaintext order cards if client-side encryption was disabled;</li><li>Normalizes customer phone numbers to international E.164 format (<code>+7XXXXXXXXXX</code>);</li><li>Checks for duplicates using the unique order identifier (<code>order_num</code>), preventing redundant entries;</li><li>Automatically creates or updates customer records in the CRM database (<code>clients</code>) and registers the order in <code>web_store_orders</code> with integer currency scaling.</li></ul></li><li><strong>Yandex Forms Import:</strong> importing orders submitted through domestic form services (CSV export from Yandex Sheets or structured manual parsing).</li><li><strong>Chat &amp; Marketplace Inquiries:</strong> copy message text to clipboard and click <strong>Smart Paste</strong>. The system extracts customer name, phone number, shipping address, and desired products.</li><li><strong>Canned Responses:</strong> click <strong>Reply</strong> to select pre-configured templates (&quot;Order Confirmed&quot;, &quot;Ready to Ship&quot;, &quot;Bank Details&quot;) with direct 1-click jump to Telegram or WhatsApp.</li><li><strong>1-Click FIFO Stock Deduction:</strong> after shipping the package, click <strong>Complete Sale</strong>. The system automatically deducts finished goods from warehouse inventory using the FIFO method and logs revenue in Cash Flow (DDS).</li><li><strong>Omnichannel &amp; Two-Phase Reservation:</strong> orders are categorized by sales channels (Website, marketplaces, offline showroom, messengers). Upon order placement, stock is reserved automatically to prevent double-selling. If available stock is insufficient, the order is flagged as &quot;On Demand&quot;. Cancelling an order releases reserved items back to available inventory immediately.</li><li><strong>Multi-Store Management:</strong> when scaling multiple independent brands or product lines (e.g., bespoke atelier vs. mass outlet), masters can create multiple storefronts within the same workspace. The header features an active store selector, while CMS Site Administration provides a dedicated Stores section for managing domains and deployment settings, publishing items independently while sharing unified inventory stock.</li></ol>',40)])])}const g=t(a,[["render",s]]);export{h as __pageData,g as default};
